import random,sys
# valid op codes per the TamaLIB table
ops=[(0xE40,0xFE0),(0x000,0xF00),(0x200,0xF00),(0x300,0xF00),(0x600,0xF00),(0x700,0xF00),(0xFE8,0xFFF),(0x400,0xF00),(0x500,0xF00),(0xFDF,0xFFF),(0xFDE,0xFFF),(0x100,0xF00),(0xFFB,0xFFF),(0xFFF,0xFFF),(0xFF8,0xFFF),(0xEE0,0xFFF),(0xEF0,0xFFF),(0xB00,0xF00),(0x800,0xF00),(0xE80,0xFFC),(0xE84,0xFFC),(0xE88,0xFFC),(0xE90,0xFFC),(0xE94,0xFFC),(0xE98,0xFFC),(0xEA0,0xFFC),(0xEA4,0xFFC),(0xEA8,0xFFC),(0xEB0,0xFFC),(0xEB4,0xFFC),(0xEB8,0xFFC),(0xA00,0xFF0),(0xA10,0xFF0),(0xA20,0xFF0),(0xA30,0xFF0),(0xA40,0xFF0),(0xA50,0xFF0),(0xA60,0xFF0),(0xA70,0xFF0),(0xE00,0xFC0),(0xEC0,0xFF0),(0xFA0,0xFF0),(0xFB0,0xFF0),(0xF80,0xFF0),(0xF90,0xFF0),(0xE60,0xFF0),(0xEE0,0xFF0),(0xE70,0xFF0),(0xEF0,0xFF0),(0x900,0xF00),(0xF40,0xFF0),(0xF50,0xFF0),(0xF41,0xFFF),(0xF5E,0xFFF),(0xF42,0xFFF),(0xF5D,0xFFF),(0xF44,0xFFF),(0xF5B,0xFFF),(0xF48,0xFFF),(0xF57,0xFFF),(0xFDB,0xFFF),(0xFCB,0xFFF),(0xFC0,0xFFC),(0xFC4,0xFFF),(0xFC5,0xFFF),(0xFC6,0xFFF),(0xFC7,0xFFF),(0xFC8,0xFFF),(0xFC9,0xFFF),(0xFCA,0xFFF),(0xFD0,0xFFC),(0xFD4,0xFFF),(0xFD5,0xFFF),(0xFD6,0xFFF),(0xFD7,0xFFF),(0xFD8,0xFFF),(0xFD9,0xFFF),(0xFDA,0xFFF),(0xFE0,0xFFC),(0xFF0,0xFFC),(0xFE4,0xFFC),(0xFF4,0xFFC),(0xC00,0xFC0),(0xA80,0xFF0),(0xC40,0xFC0),(0xA90,0xFF0),(0xAA0,0xFF0),(0xD40,0xFC0),(0xAB0,0xFF0),(0xC80,0xFC0),(0xAC0,0xFF0),(0xCC0,0xFC0),(0xAD0,0xFF0),(0xD00,0xFC0),(0xAE0,0xFF0),(0xDC0,0xFC0),(0xF00,0xFF0),(0xD80,0xFC0),(0xF10,0xFF0),(0xAF0,0xFF0),(0xE8C,0xFFC),(0xF60,0xFF0),(0xF70,0xFF0),(0xF28,0xFFC),(0xF2C,0xFFC),(0xF38,0xFFC),(0xF3C,0xFFC),(0xD0F,0xFCF)]
random.seed(int(sys.argv[1])); out=bytearray()
for i in range(8192):
  while True:
    c,m=random.choice(ops); op=c|(random.getrandbits(12)&~m&0xFFF)
    if op==0xFF8 and random.random()<0.7: continue
    break
  out+=bytes([op>>8,op&0xFF])
open(sys.argv[2],'wb').write(out)
